 "panel.css": "/* The homepage demo's additions to the real side panel (shim.js puts the next recorded prompt in the message box). */\n\n/* Dark, like the page around it, whatever the visitor's system is set to: the panel's colours are\n   light-dark() pairs, which follow color-scheme. (Its one light-only rule, the sleeping robot's\n   opacity, is put back to the dark values.) */\n:root { color-scheme: dark; }\n/* Text at the size it's set: iPhone Safari's text autosizing otherwise enlarges the chat when the sheet\n   is swiped away (squashed to its bar) and brought back. */\nhtml { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }\nbody.site-off .bar-robot svg { opacity: 0.45; }\nbody.site-off .bar-robot:hover:not([aria-busy=\"true\"]) svg { opacity: 0.7; }\n\n/* The panel's own suggestions (\"Hide distractions\"…) would only get \"this demo replays recordings\":\n   the recorded prompt waiting in the message box takes their place. */\n#empty .chips { display: none; }\n\n/* Send pulses while a recorded prompt waits for it, so it's clear what to do (shim.js). */\nhtml.demo-hint-send #send:not([hidden], :disabled) { animation: demo-send-pulse 1.6s ease-out infinite; }\n@keyframes demo-send-pulse {\n  0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent) 80%, transparent); }\n  70%, 100% { box-shadow: 0 0 0 9px color-mix(in srgb, var(--accent) 0%, transparent); }\n}\n@media (prefers-reduced-motion: reduce) {\n  html.demo-hint-send #send:not([hidden], :disabled) { animation: none; box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 60%, transparent); }\n}\n\n/* Until every recording has played, the message box holds the next recorded prompt and can't be typed in\n   or focused (on a phone: no keyboard, no zooming in on it); Send replays it (shim.js). */\nhtml.demo-guided #input { pointer-events: none; caret-color: transparent; }\n/* Stop does nothing to a recorded chat (it plays to its end: shim.js), so it's shown locked */\n#stop { pointer-events: none; opacity: 0.45; }\n/* The robot has locked the chat (shim.js: after the last of its replies to typing) */\nhtml.demo-locked .composer { opacity: 0.5; pointer-events: none; }\n/* On a phone, everything the visitor could still focus (the settings) is at least 16px, or the phone zooms\n   the page in on it. */\nhtml.demo-phone #input { font-size: 16px; }\nhtml.demo-phone :is(input, select, textarea) { font-size: 16px; }\n\n/* On a phone nothing in the panel pans the page under it: only what has something to scroll right now\n   (shim.js marks it) can be panned; every other swipe is the panel's own (it moves the sheet: shim.js). */\nhtml.demo-phone, html.demo-phone body { touch-action: none; }\nhtml.demo-phone .demo-scrolls-y { touch-action: pan-y; }\nhtml.demo-phone .demo-scrolls-x { touch-action: pan-x; }\n\n/* Scrolling inside the panel stays inside it: the page under the demo doesn't scroll along when a list\n   reaches its end (shim.js also stops swipes on the parts that don't scroll at all). */\nhtml, body { overscroll-behavior: none; }\n* { overscroll-behavior: contain; }\n\n/* On a phone the panel is a short sheet (40% of the screen): everything a little tighter, so the chat\n   keeps some room and the message box and Send stay in view. */\nhtml.demo-phone .bar { padding: 5px 8px 5px 12px; }\nhtml.demo-phone .mods { margin: 6px 10px 0; padding: 5px 10px; }\nhtml.demo-phone .mod-list { max-height: calc(34vh - 30px); }\nhtml.demo-phone .mod-list li { padding: 3px 0; }\nhtml.demo-phone .chat { padding: 8px 12px 2px; }\nhtml.demo-phone .composer { margin: 4px 10px 8px; }\n/* The message box fits its text (shim.js sizes it: Safari can't yet), and the sheet grows to make room\n   (tab.js); past eight lines it scrolls. */\nhtml.demo-phone .composer textarea { padding: 6px 40px 6px 10px; max-block-size: calc(8lh + 14px); overflow-y: auto; }\n/* The waiting prompt, two lines at a time: it scrolls with a finger (and follows the typing), but still\n   can't be focused (shim.js), and 16px, so a phone never zooms in on it. */\nhtml.demo-phone.demo-guided #input { pointer-events: auto; overflow-y: auto; font-size: 16px;\n  max-block-size: calc(8lh + 14px); -webkit-user-select: none; user-select: none; }\n"
